/**
 * By-hand headless soak: npm run test:soak:headless (never in CI).
 *
 * buildSim() mirrors src/main.ts up to `new Sim(…)` (generated by
 * Baton/scripts/generate-headless-soak.mjs; keep it in sync when main.ts changes). The
 * harness in tests/helpers/headlessSoak.ts (template-owned) presses every control, sets
 * every slider, steps, switches screens, flips the color profile and locale, presses
 * Reset All, and fails when listener counts, node counts or retained heap rise after
 * every round.
 *
 * Add `exclude` for controls that must not be pressed headless and `actions` for what
 * only this sim can do (record/clear, add/remove objects).
 */

import { Tandem } from "scenerystack/tandem";
import { StringManager } from "../../src/i18n/StringManager.js";
import OscilloscopeColors from "../../src/OscilloscopeColors.js";
import { OscilloscopeScreen } from "../../src/oscilloscope-screen/OscilloscopeScreen.js";
import { OscilloscopePreferencesModel } from "../../src/preferences/OscilloscopePreferencesModel.js";
import { describeHeadlessSoak } from "../helpers/headlessSoak.js";

function buildSim() {
  const stringManager = StringManager.getInstance();

  // Simulation-specific preferences; initial values come from oscilloscopeQueryParameters.
  const simPreferences = new OscilloscopePreferencesModel(Tandem.ROOT.createTandem("preferences"));

  const screens = [
    new OscilloscopeScreen({
      // The screen name Property updates automatically when the locale changes
      name: stringManager.getScreenNames().simStringProperty,
      tandem: Tandem.ROOT.createTandem("simScreen"),
      backgroundColorProperty: OscilloscopeColors.backgroundColorProperty,
      // Shared preference: whether the on-screen measurement readout is drawn.
      showMeasurementsProperty: simPreferences.showMeasurementsProperty,
      // Shared preferences: signal-noise injection, read live by the generator.
      noiseEnabledProperty: simPreferences.noiseEnabledProperty,
      noiseAmplitudeProperty: simPreferences.noiseAmplitudeProperty,
    }),
  ];

  return { screens, tracked: { OscilloscopeColors, stringManager, simPreferences } };
}

let sim: ReturnType<typeof buildSim> | undefined;

describeHeadlessSoak({
  screens: () => {
    sim = buildSim();
    return sim.screens;
  },
  tracked: () => sim?.tracked ?? {},
});
